(()=>{const KEY='theme';const root=document.documentElement;const media=window.matchMedia('(prefers-color-scheme: dark)');const read=()=>{try{return window.localStorage.getItem(KEY);}catch{return null;}};const store=(value)=>{try{if(value)window.localStorage.setItem(KEY,value);else window.localStorage.removeItem(KEY);}catch{}};const stored=read();if(stored==='light'||stored==='dark')root.dataset.theme=stored;const isDark=()=>(root.dataset.theme||(media.matches?'dark':'light'))==='dark';document.addEventListener('DOMContentLoaded',()=>{const button=document.querySelector('.theme-toggle');if(!button)return;const sync=()=>button.setAttribute('aria-pressed',String(isDark()));button.hidden=false;sync();button.addEventListener('click',()=>{const next=isDark()?'light':'dark';if((next==='dark')===media.matches){delete root.dataset.theme;store(null);}else{root.dataset.theme=next;store(next);}
sync();});media.addEventListener('change',sync);});})();